+package com.example;
+
+import java.util.regex.Pattern;
+
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL = Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
+
+    private final ContactMessageStore messageStore;
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+    private final Grid<SentMessage> sentMessages = new Grid<>(SentMessage.class, false);
+
+    private boolean clearingForm;
+
+    public ContactView(ContactMessageStore messageStore) {
+        this.messageStore = messageStore;
+
+        add(new H1("Contact"), new RouterLink("About", AboutView.class));
+
+        message.setMaxLength(501);
+        send.addClickListener(event -> sendMessage());
+        send.addClickShortcut(Key.ENTER);
+
+        name.addValueChangeListener(event -> enableAfterEdit());
+        email.addValueChangeListener(event -> enableAfterEdit());
+        phone.addValueChangeListener(event -> enableAfterEdit());
+        message.addValueChangeListener(event -> enableAfterEdit());
+
+        sentMessages.addColumn(SentMessage::name).setHeader("Name");
+        sentMessages.addColumn(SentMessage::message).setHeader("Message");
+        sentMessages.setItems(messageStore.all());
+
+        add(name, email, phone, message, send, sentMessages);
+    }
+
+    private void enableAfterEdit() {
+        if (!clearingForm) {
+            send.setEnabled(true);
+        }
+    }
+
+    private void sendMessage() {
+        clearValidation();
+        if (!isValidForm()) {
+            return;
+        }
+
+        messageStore.add(new SentMessage(name.getValue(), email.getValue(), phone.getValue(), message.getValue()));
+        sentMessages.setItems(messageStore.all());
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private boolean isValidForm() {
+        boolean valid = true;
+        String nameValue = name.getValue().trim();
+        String emailValue = email.getValue().trim();
+        String phoneValue = phone.getValue().trim();
+        String messageValue = message.getValue().trim();
+
+        if (nameValue.isEmpty()) {
+            invalid(name, "Name is required");
+            valid = false;
+        }
+        if (!emailValue.isEmpty() && !EMAIL.matcher(emailValue).matches()) {
+            invalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isEmpty() && phoneValue.isEmpty()) {
+            invalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+        if (messageValue.isEmpty()) {
+            invalid(message, "Message is required");
+            valid = false;
+        } else if (message.getValue().length() > 500) {
+            invalid(message, "Message must be at most 500 characters");
+            valid = false;
+        }
+        return valid;
+    }
+
+    private void invalid(com.vaadin.flow.component.HasValidation field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearValidation() {
+        clearValidation(name);
+        clearValidation(email);
+        clearValidation(phone);
+        clearValidation(message);
+    }
+
+    private void clearValidation(com.vaadin.flow.component.HasValidation field) {
+        field.setInvalid(false);
+        field.setErrorMessage(null);
+    }
+
+    private void clearForm() {
+        clearingForm = true;
+        name.clear();
+        email.clear();
+        phone.clear();
+        message.clear();
+        clearingForm = false;
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasDraft()) {
+            return;
+        }
+
+        BeforeLeaveEvent.ContinueNavigationAction navigation = event.postpone();
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        Button keepEditing = new Button("Keep editing", click -> dialog.close());
+        Button discard = new Button("Discard", click -> {
+            dialog.close();
+            navigation.proceed();
+        });
+        dialog.add(keepEditing, discard);
+        dialog.open();
+    }
+
+    private boolean hasDraft() {
+        return !name.getValue().isEmpty()
+                || !email.getValue().isEmpty()
+                || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+}
